        <Frame pad="12px 14px" style={{ display: "flex", gap: 12, alignItems: "center", marginTop: 4 }}>
          <Icon n="book" s={40} />
          <div style={{ fontSize: 15, color: C.label, lineHeight: 1.45 }}>No grimoire is chosen here. At the ceremony a grimoire decides whether you are its owner, three leaves or something rarer. You find out by living.</div>
        </Frame>
      </div>
    );
  } else if (page === 3) {
    body = (
      <div>
        {!f.homeland ? <Empty>Choose a homeland on the Background page first.</Empty> : (
          <div>
            <Field label="Region"><Seg label="Region" value={f.region} options={regions.map(function (r) { return r.r; })} onChange={function (x) { setMany({ region: x, settlement: "", settlement_mode: "" }); }} /></Field>
            {regionObj ? (
              <Field label="Home">
                {regionObj.s.map(function (s) {
                  return <Opt key={s.n} on={f.settlement === s.n} title={s.n} desc={s.d} tag={s.c === "canon" ? "Canon" : "Generated"} onClick={function () { setMany({ settlement: s.n, settlement_mode: s.c }); }} />;
                })}
                <Opt on={f.settlement_mode === "custom"} title="A place I describe" tag="Custom" onClick={function () { setMany({ settlement: "Custom place", settlement_mode: "custom" }); }} />
                {f.settlement_mode === "custom" ? <textarea className="bc-in bc-ta" aria-label="Custom home" placeholder="For example: a tiny mountain village where most families raise sheep" value={f.custom_place} onChange={function (e) { set("custom_place", e.target.value); }} /> : null}
              </Field>
            ) : <Empty>Choose a region to see places to live.</Empty>}
          </div>
        )}
      </div>
    );
  } else {
    var eraT = ""; ERA_TILES.forEach(function (x) { if (x.v === f.era) eraT = x.t.replace("\n", " "); });
    var place = f.settlement_mode === "custom" ? (str(f.custom_place).slice(0, 60) || "A place you describe") : f.settlement;
    var rows = [
      { k: "Name", v: f.name, pg: 0 }, { k: "Gender", v: f.sex, pg: 0 }, { k: "Age", v: str(f.age), pg: 0 },
      { k: "Birthday", v: (f.birth_month || "March") + " " + (f.birth_day || 14), pg: 0 },
      { k: "Story timing", v: eraT + ": " + (f.era === "custom" ? f.era_detail : f.opening), pg: 0 },
      { k: "Homeland", v: f.homeland, pg: 1 }, { k: "Origin", v: f.origin + (f.origin_detail ? ", " + f.origin_detail : ""), pg: 1 }, { k: "Family", v: f.family_mode, pg: 1 },
      { k: "Magic", v: f.magic_mode === "Random" ? "Random" : (f.magic_mode === "Choose" ? f.attribute_choice : "Described by you"), pg: 2 },
      { k: "Talent", v: f.talent_mode === "Natural" ? "Natural simulation" : (f.talent_mode === "Guided" ? "Guided" : "Full sandbox"), pg: 2 },
      { k: "Home", v: (f.region ? f.region + ": " : "") + place, pg: 3 }
    ];
    body = (
      <div>
        <div className="bc-final-lead">
          <div className="bc-final-portrait">{art.portrait ? <img src={art.portrait} alt="Your character" /> : <Icon n="bust" s={48} />}</div>
          <div className="bc-final-caption"><span>Ready to begin</span><strong>{f.name || "Your character"}</strong><small>{[f.homeland, f.origin, f.magic_mode === "Choose" ? f.attribute_choice : ""].filter(Boolean).join(" · ")}</small></div>
        </div>
        <Frame className="bc-final-review" pad="11px 13px" style={{ marginBottom: 16 }}>
        <H size={17} m="0 0 6px">Your life so far</H>
        <div style={{ fontSize: 14.5, color: C.muted, marginBottom: 6 }}>Tap a line to change it. Your grimoire and anything rare are decided by the world as you live.</div>
