function PackView(p) {
  var api=p.api, v=api.variables||{}, busy=!!api.isStreaming;
  var inv=bcNormalize(arr(v.inventory),v);
  var carry=bcCarryProfile(inv,obj(v.body_profile),bcWalletProfile(v.money).weightKg);
  var ss=React.useState('containers'),page=ss[0],setPage=ss[1];
  var sel=React.useState({}),chosen=sel[0],setChosen=sel[1];
  var msgState=React.useState(''),msg=msgState[0],setMsg=msgState[1];
  var atHome=!!str(v.home_location) && str(v.home_location)===str(v.current_location);
  var can=!busy && canWrite(api);
  var homeUsed=bcHomeUsed(inv,str(v.home_location));
  var atSquad=bcAtSquadLocker(v),squadUsed=bcWorldStoreUsed(inv,'storage',str(v.current_location));
  function persist(list,verb,it,kind,minutes) {
    if(!can)return;
    var normalized=bcNormalize(list,v);
    var appearance=bcAppearance(normalized,v);
    var existing=arr(v.equipment_activity);
    var nextId='gear-'+(num(v.equipment_event_seq,0)+1);
    var line=bcEventText(kind,it,normalized,appearance);
    var prev=obj(v.appearance_state);
    appearance.lastChangedId=nextId;
    var event={id:nextId,kind:kind,itemId:it&&it.id,item:it&&it.name,
      text:line,location:str(v.current_location),at:str(v.world_time),
      appearance:appearance.coverage,meaningful:kind==='equip'||kind==='remove'||kind==='drop',
      // Observation is not automatic: GM checks witnesses on the next story turn.
      observed:false};
    var patch=Object.assign({inventory:normalized,carry_state:bcCarryProfile(normalized,obj(v.body_profile),bcWalletProfile(v.money).weightKg),
      appearance_state:appearance,equipment_activity:existing.concat([event]).slice(-6),
      equipment_event_seq:num(v.equipment_event_seq,0)+1},bcClockForInventory(v,minutes==null?1:minutes));
    try {
      var result=typeof api.patchVariables==='function'?api.patchVariables(patch):null;
      if(typeof api.patchVariables!=='function')Object.keys(patch).forEach(function(k){api.setVariable(k,patch[k]);});
      setMsg(line);
      if(result&&typeof result.catch==='function') result.catch(function(){setMsg('Inventory update could not be saved.');});
    }catch(e){setMsg('Save failed: '+str(e&&e.message||e));}
  }
  function move(it,dest,caption,qty) {
    var res=bcMoveQty(inv,it.id,dest,v,qty);
    if(!res.ok){setMsg(res.reason);return;}
    var wasWorn=it.placement&&it.placement.kind==='body';
    var kind=dest.kind==='body'?'equip':dest.kind==='world'?'drop':wasWorn?'remove':caption==='Retrieved'?'retrieve':dest.kind==='container'?'store':'move';
    if(dest.kind==='world'&&dest.area==='home')kind='store';
    persist(res.inventory,caption,it,kind,kind==='equip'||kind==='remove'?2:1);
  }
  function useItem(it) {
    if(!bcIsAccessible(it,inv,isTrue(v.in_combat))){setMsg('You cannot reach that item.');return;}
    if(bcCanConsume(it) && !isTrue(v.in_combat)){
      var result=bcConsume(inv,it.id,v);
      if(result.ok){persist(result.inventory,'Used',it,'consume',4);return;}
      setMsg(result.reason);return;
    }
    // A tool's magic, weapon attack, medicine or NPC-dependent use is a scene,
    // not a deterministic inventory transaction; let the player choose a GM call.
    setMsg('This needs a story action. Select “Use in story (AI)” to resolve it.');
  }
  function itemCard(it) {
    var pl=it.placement||{},sp=bcSpec(it),wt=bcWeight(it),b=bcBulk(it),qty=num(it.qty,1),worn=pl.kind==='body';
    var carried=bcCarried(it,inv),stored=pl.kind==='world';
    var easy=bcIsAccessible(it,inv,isTrue(v.in_combat));
    var destinations=carried?bcDestinations(inv,it):[];
    var rawSel=chosen[it.id],selKey=destinations.some(function(d){return JSON.stringify(d.placement)===rawSel;})?rawSel:(destinations[0]?JSON.stringify(destinations[0].placement):'');
    var selDest=destinations.find(function(d){return JSON.stringify(d.placement)===selKey;});
    var equippable=bcAllowedSlots(it);
    var inaccessible=stored && !(pl.location===str(v.current_location) || (pl.area==='home'&&atHome));
    return (
      <div key={it.id} style={{padding:'11px 0',borderBottom:'1px solid '+C.lineSoft}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:8,flexWrap:'wrap'}}>
          <div style={{minWidth:0,flex:'1 1 140px'}}>
            <div style={{color:C.ivory,fontSize:16,fontWeight:650}}>{str(it.name)+(qty>1?' ×'+qty:'')}{sp.storage?' · '+BC_STORAGE[sp.storage].label:''}</div>
            <div style={{color:C.muted,fontSize:12.5,marginTop:3}}>{bcPlaceLabel(inv,it)}</div>
            {it.cond?<div style={{color:C.faint,fontSize:12,marginTop:3}}>{'Condition: '+str(it.cond)+(it.durability!==undefined?' · '+num(it.durability)+' durability':'')}</div>:null}
          </div>
          <div style={{color:C.goldHi,fontSize:12.5,textAlign:'right',whiteSpace:'nowrap'}}>{wt+' kg · '+b+' bulk'}</div>
        </div>
        <div style={{display:'flex',gap:6,flexWrap:'wrap',marginTop:9}}>
          {carried?<Btn small disabled={!can||!easy} onClick={function(){useItem(it);}}>Use (local)</Btn>:null}
          <Btn small disabled={busy} onClick={function(){setMsg(bcLocalExamine(it,inv));}}>Examine (free)</Btn>
          {carried?<Btn small disabled={!can||!easy} onClick={function(){send(api,'[UI:ACT] I use '+str(it.name)+' ('+it.id+') from '+bcPlaceLabel(inv,it)+'. Resolve effects and witnesses from world state. Do not repeat any already-applied inventory transfer.');p.toStory();}}>Use in story (AI)</Btn>:null}
          <Btn small disabled={busy} onClick={function(){send(api,'[UI:ACT] I examine '+str(it.name)+' ('+it.id+') carefully for details beyond its recorded description.');p.toStory();}}>Inspect in story (AI)</Btn>
          {carried&&equippable.map(function(slot){return <Btn key={slot} small disabled={!can||(worn&&pl.slot===slot)} onClick={function(){move(it,{kind:'body',slot},'Equipped');}}>{worn&&pl.slot===slot?'Equipped':(slot==='main-hand'||slot==='off-hand'?'Wield · ':'Wear · ')+(BC_SLOTS.find(function(x){return x[0]===slot;})||['',slot])[1]}</Btn>;})}
          {worn?<Btn small disabled={!can} onClick={function(){var spot=bcFindSpot(inv,it);if(!spot){setMsg('Free room in a bag or your arms before removing this item.');return;}move(it,spot,'Removed');}}>Take off / Sheathe</Btn>:null}
          {stored&&!inaccessible?<Btn small disabled={!can} onClick={function(){var spot=bcFindSpot(inv,it);if(!spot){setMsg('No free space to retrieve '+it.name+'.');return;}move(it,spot,'Retrieved');}}>Retrieve</Btn>:null}
          {carried?<Btn small disabled={!can} onClick={function(){move(it,{kind:'world',area:'ground'},'Dropped');}}>Drop</Btn>:null}
          {carried&&qty>1?<Btn small disabled={!can} onClick={function(){move(it,{kind:'world',area:'ground'},'Dropped one',1);}}>Drop 1</Btn>:null}
          {carried&&atHome?<Btn small disabled={!can} onClick={function(){move(it,{kind:'world',area:'home'},'Stored at home');}}>Store at home</Btn>:null}
          {carried&&atSquad?<Btn small disabled={!can} onClick={function(){move(it,{kind:'world',area:'storage'},'Stored at squad locker');}}>Squad locker</Btn>:null}
        </div>
        {carried&&destinations.length?(
          <div style={{display:'flex',alignItems:'center',gap:7,marginTop:9,flexWrap:'wrap'}}>
            <select aria-label={'Move '+str(it.name)+' to'} value={selKey} onChange={function(e){setChosen(Object.assign({},chosen,{[it.id]:e.target.value}));}} style={{background:'#15171a',color:C.ivory,border:'1px solid '+C.line,borderRadius:5,padding:'8px',maxWidth:'100%',flex:'1 1 160px',fontSize:13}}>
              {destinations.map(function(d,i){return <option key={i} value={JSON.stringify(d.placement)}>{d.label}</option>;})}
            </select>
            <Btn small disabled={!can||!selDest} onClick={function(){if(selDest)move(it,selDest.placement,'Moved');}}>Move</Btn>
          </div>
        ):null}
        {sp.storage ? (
          <div style={{marginTop:10,padding:'6px 9px',background:'rgba(201,162,78,.055)',border:'1px solid '+C.lineSoft,borderRadius:5}}>
            {BC_STORAGE[sp.storage].slots.map(function(slot){
              var present=inv.filter(function(x){var xpl=x.placement||{};return xpl.kind==='container'&&xpl.containerId===it.id&&xpl.slotId===slot.id;});
              var load=present.reduce(function(n,x){return n+bcBulk(x);},0),mass=present.reduce(function(n,x){return n+bcWeight(x);},0);
              return <div key={slot.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,padding:'4px 0',fontSize:12.5,color:C.label}}><span>{slot.label+' · '+slot.access}{present.length?' ('+present.map(function(x){return x.name}).join(', ')+')':''}</span><span style={{whiteSpace:'nowrap',color:load>slot.bulkCap||mass>slot.weightCap?'#e7a2a2':C.muted}}>{Math.round(load*10)/10+'/'+slot.bulkCap+' bulk'}</span></div>;
            })}
          </div>
        ):null}
      </div>
    );
  }
  var equipped=inv.filter(function(it){return it.placement&&it.placement.kind==='body';});
  var bags=inv.filter(function(it){return bcStorageOf(it)&&bcCarried(it,inv);});
  var carried=inv.filter(function(it){return bcCarried(it,inv);});
  var outside=inv.filter(function(it){return !bcCarried(it,inv);});
  var show=page==='equipment'?equipped:page==='containers'?bags:page==='away'?outside:carried;
  var over=carry.band==='overloaded'||carry.band==='immobile';
  var appearance=bcAppearance(inv,v);
  return (
    <div>
      <Eyebrow k="PHYSICAL INVENTORY · CLOVER KINGDOM">Every item occupies actual space.</Eyebrow>
      <Frame pad="10px 14px" style={{marginBottom:12}}>
        <H m="0 0 7px">Visible appearance</H>
        <div style={{fontSize:14.5,color:C.ivory}}>{appearance.summary}</div>
        {appearance.social?<div style={{marginTop:9,paddingTop:9,borderTop:'1px solid '+C.lineSoft}}>
          <div style={{fontSize:13.5,color:C.goldHi}}>Social presentation · {appearance.social.outfitTier} dress{appearance.social.condition!=='no visible damage recorded'?' · '+appearance.social.condition:''}</div>
          <div style={{fontSize:12.5,color:C.muted,marginTop:4}}>Setting: {appearance.social.setting} · Etiquette scrutiny: {appearance.social.scrutiny}</div>
          <div style={{fontSize:12.5,color:C.muted,marginTop:4}}>Background: {appearance.social.origin} (not automatically known to strangers)</div>
          {appearance.social.visibleSignals.length?<div style={{fontSize:12.5,color:C.label,marginTop:4}}>{appearance.social.visibleSignals.join(' · ')}</div>:null}
          {appearance.social.socialNotes.length?<div style={{fontSize:12.5,color:C.muted,marginTop:4}}>{appearance.social.socialNotes.slice(0,2).join(' · ')}</div>:null}
        </div>:null}
        {appearance.visibleArmor.length?<div style={{fontSize:12.5,color:C.muted,marginTop:5}}>{'Armor: '+appearance.visibleArmor.join(', ')}</div>:null}
        {appearance.drawnWeapons.length?<div style={{fontSize:12.5,color:C.muted,marginTop:5}}>{'In hand: '+appearance.drawnWeapons.join(', ')}</div>:null}
        {appearance.coverage!=='dressed'?<div style={{fontSize:12.5,color:'#e7b5a4',marginTop:6}}>{'Dress: '+appearance.inadequatelyDressed.join('; ')+'. NPCs may notice if present.'}</div>:null}
        <div style={{fontSize:12,color:C.muted,marginTop:7}}>Equipment actions are free of AI calls; complex uses and dialogue can be requested separately.</div>
      </Frame>
      <Frame pad="12px 14px" style={{marginBottom:13}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:12,flexWrap:'wrap'}}><span style={{color:C.muted}}>Your purse</span><strong style={{fontSize:19,fontFamily:DISPLAY,color:C.goldHi}}>{num(v.money,0).toLocaleString()+' yul'}</strong></div>
        <div style={{fontSize:12.5,color:C.muted,marginTop:4}}>{'Purse mass: '+bcWalletProfile(v.money).weightKg.toFixed(3)+' kg · '+bcWalletProfile(v.money).pieces+' notes/coins · bank: '+bcMoney(bcBankState(v.bank_account).balance)}</div>
        <Btn small onClick={function(){p.goBank();}}>Bank / Treasury</Btn>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,marginTop:12,fontSize:13,color:C.label}}><span>{'Carry load · '+carry.band}</span><span>{carry.weight+' / '+carry.max+' kg'}</span></div>
        <div style={{height:9,borderRadius:8,margin:'7px 0 4px',background:'#111215',overflow:'hidden',border:'1px solid '+C.line}}><div style={{height:'100%',width:Math.min(100,100*carry.weight/Math.max(1,carry.max))+'%',background:over?'#ae7060':C.gold,transition:'width .2s'}} /></div>
        <div style={{fontSize:12,color:C.muted}}>{'Comfortable ≤ '+carry.comfortable+' kg · Heavy ≤ '+carry.heavy+' kg · Arms '+carry.armsBulk+' / '+BC_ARMS_BULK+' bulk'}</div>
        {carry.band!=='comfortable'?<div style={{fontSize:12.5,color:over?'#f1b8a8':C.goldHi,marginTop:8}}>{carry.band==='immobile'?'Immobile: drop weight before moving.':carry.band==='overloaded'?'Overloaded: substantial penalties to travel, dodging and stamina.':'Heavy: movement and stamina are impaired.'}</div>:null}
      </Frame>
      <div style={{display:'flex',flexWrap:'wrap',gap:6,marginBottom:12}}>
        {[['containers','Containers'],['equipment','Equipped'],['carried','Carried'],['away','Elsewhere']].map(function(tab){return <Btn key={tab[0]} small kind={page===tab[0]?'gold':undefined} onClick={function(){setPage(tab[0]);setMsg('');}}>{tab[1]+(tab[0]==='away'?' ('+outside.length+')':'')}</Btn>;})}
      </div>
      {msg?<div role="status" style={{fontSize:13,margin:'0 0 10px',color:C.goldHi,borderLeft:'2px solid '+C.gold,padding:'5px 9px'}}>{msg}</div>:null}
      {page==='equipment'?<Frame pad="10px 12px" style={{marginBottom:10}}><H m="0 0 7px">Equipment slots</H>{BC_SLOTS.map(function(pair){var equippedIt=equipped.find(function(x){return x.placement.slot===pair[0]});return <Row key={pair[0]} k={pair[1]} v={equippedIt?str(equippedIt.name):'—'} />;})}<div style={{fontSize:12,color:C.muted,marginTop:8}}>Your grimoire is tracked separately on the Grimoire page.</div></Frame>:null}
      {page==='containers'&&!bags.length?<Empty>No carried containers. A travel satchel, belt pouch, field pack or magic-tool case provides physical compartments.</Empty>:null}
      {page==='away'&&!outside.length?<Empty>No possessions recorded outside your carried equipment.</Empty>:null}
      {page==='carried'&&!carried.length?<Empty>Your hands and pockets are empty.</Empty>:null}
      {(page!=='containers'||bags.length)&&show.length?<Frame pad="4px 12px 10px">{show.map(itemCard)}</Frame>:null}
      {page==='containers'&&bags.length?<div style={{margin:'10px 0 0',fontSize:12.5,color:C.muted}}>Choose Carried to move individual contents between compartments. A pack retains its contents when dropped or stored.</div>:null}
    </div>
  );
}


function BankView(p) {
  var api=p.api,v=api.variables||{},bank=bcBankState(v.bank_account),wallet=bcWalletProfile(v.money);
  var here=bcBankHere(v),ready=canWrite(api);
  var amountState=React.useState(''),amount=amountState[0],setAmount=amountState[1];
  var msgState=React.useState(''),msg=msgState[0],setMsg=msgState[1];
  var pending=React.useRef(false);
  var startSignature=React.useRef('');
  var stateSignature=JSON.stringify([v.money,v.bank_account]);
  React.useEffect(function(){if(pending.current&&stateSignature!==startSignature.current) pending.current=false;},[stateSignature]);
  function apply(patch,success){
    if(pending.current||!ready)return;
    pending.current=true;startSignature.current=stateSignature;
    try{
      var result;
      if(typeof api.patchVariables==='function')result=api.patchVariables(patch);
      else Object.keys(patch).forEach(function(k){api.setVariable(k,patch[k]);});
      if(result&&typeof result.then==='function')result.then(function(){setMsg(success);},function(){pending.current=false;setMsg('Transaction could not be saved. Please check the balances before trying again.');});
      else setMsg(success);
    }catch(e){pending.current=false;setMsg('Save failed: '+str(e&&e.message||e));}
  }
  function open(){
    var r=bcBankOpen(v.bank_account,v);
    if(!r.ok){setMsg(r.reason);return;}
    apply(Object.assign({bank_account:r.bank_account},bcClockForInventory(v,5)),'Account opened. Deposits and withdrawals can now be completed at a staffed branch.');
  }
  function transfer(kind,n){
    if(pending.current)return;
    var r=bcBankTransfer(v,kind,n);
    if(!r.ok){setMsg(r.reason);return;}
    var inv=bcNormalize(arr(v.inventory),v);
    var patch=Object.assign({money:r.money,bank_account:r.bank_account,
      carry_state:bcCarryProfile(inv,obj(v.body_profile),bcWalletProfile(r.money).weightKg)},bcClockForInventory(v,3));
    apply(patch,(kind==='deposit'?'Deposited ':'Withdrew ')+bcMoney(n)+'; both balances have been updated.');
    setAmount('');
  }
  return <div>
    <Eyebrow k="CLOVER KINGDOM · TREASURY & BANKING">Funds on account have no carried mass.</Eyebrow>
    <Frame pad="13px 14px" style={{marginBottom:12}}>
      <Row k="Purse · spendable cash" v={bcMoney(v.money)}/>
      <Row k="Purse weight" v={wallet.weightKg.toFixed(3)+' kg ('+wallet.pieces+' pieces)'}/>
      <Row k="Secure account" v={bcMoney(bank.balance)}/>
      <Row k="Account" v={bank.open?'Active':'Not opened'}/>
      <Row k="Current premises" v={str(v.current_location)||'Unknown'}/>
      <div style={{fontSize:13,color:here?C.goldHi:C.muted,marginTop:10}}>{here?'Staffed financial counter available: local deposits and withdrawals are enabled.':'You can inspect your balance here, but transactions require visiting an actual bank or treasury office.'}</div>
      {here&&!bank.open?<div style={{marginTop:12}}><Btn kind="gold" disabled={!ready} onClick={open}>Open a free account</Btn></div>:null}
    </Frame>
    <Frame pad="12px 14px" style={{marginBottom:12}}>
      <H m="0 0 7px">Transfer Yul</H>
      <Field label="Amount (whole Yul)"><input className="bc-in" inputMode="numeric" type="number" min="1" step="1" aria-label="Yul transfer amount" value={amount} onChange={function(e){setAmount(e.target.value);}} placeholder="Enter amount" /></Field>
      <div style={{display:'flex',gap:8,flexWrap:'wrap',marginTop:10}}>
        <Btn small disabled={!ready||!here||!bank.open||!(Number(amount)>0)} onClick={function(){transfer('deposit',Number(amount));}}>Deposit</Btn>
        <Btn small disabled={!ready||!here||!bank.open||!(Number(amount)>0)} onClick={function(){transfer('withdraw',Number(amount));}}>Withdraw</Btn>
        <Btn small disabled={!ready||!here||!bank.open||wallet.yul<=0} onClick={function(){transfer('deposit',wallet.yul);}}>Deposit all cash</Btn>
      </div>
      {msg?<div role="status" style={{color:C.goldHi,fontSize:13,marginTop:9}}>{msg}</div>:null}
      <div style={{fontSize:12.5,color:C.muted,marginTop:9}}>Deposits reduce the physical purse. Withdrawals add cash to the purse. Bank balances cannot be spent at an ordinary stall until withdrawn.</div>
    </Frame>
    <H m="16px 0 8px">Recent account activity</H>
    {bank.ledger.length?<Frame pad="4px 13px">{bank.ledger.slice(-12).reverse().map(function(e,i){return <div key={e.id||i} style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',gap:8,padding:'9px 0',borderBottom:'1px solid '+C.lineSoft}}><div style={{fontSize:13.5,color:C.label}}>{str(e.kind)+' · '+str(e.at)}</div><div style={{fontSize:14,color:C.goldHi}}>{e.kind==='withdraw'?'-':'+'}{bcMoney(e.amount)}</div></div>;})}</Frame>:<Empty>No banking transactions have been recorded.</Empty>}
    <div style={{marginTop:12}}><Btn small disabled={!!api.isStreaming} onClick={function(){send(api,"I ask where the nearest reputable banking or treasury office is and how to reach it.");p.toStory();}}>Ask where to bank (AI, optional)</Btn></div>
    <div style={{fontSize:12,color:C.muted,marginTop:12}}>A Magic Knight's salary and approved awards are automatically credited to a protected treasury account on payday. Opening and transfer actions are local and do not use AI. Exact institutional banking arrangements and denomination weights are game-world reconstructions, not declared Black Clover canon.</div>
  </div>;
}

function MarketView(p) {
  var api = p.api; var v = api.variables || {}; var busy = !!api.isStreaming; var locs = arr(v.known_locations); var cx = arr(v.codex);
  var shopRe = /shop|market|merchant|smith|baker|store|stall|inn|tavern|trader|emporium/i; var blackRe = /black market|black-market|smuggl|fence|underground|contraband/i;
  var shops = locs.filter(function (l) { return shopRe.test(str(l.name) + " " + str(l.notes)) && !blackRe.test(str(l.name) + " " + str(l.notes)); });
  var shady = locs.filter(function (l) { return blackRe.test(str(l.name) + " " + str(l.notes)); }).concat(cx.filter(function (c) { return blackRe.test(str(c.topic) + " " + str(c.text)); }));
  var stock = arr(v.shop_stock);
  function ask(t) { send(api, t); p.toStory(); }
  var buyMessage=React.useState(''),buyError=buyMessage[0],setBuyError=buyMessage[1];
  function buyItem(item, idx) {
    if(!canWrite(api)||num(item.qty,1)<=0)return;
    var price=num(item.price,0);
    if(price<0||num(v.money,0)<price){setBuyError('Not enough yul.');return;}
    var current=bcNormalize(arr(v.inventory),v);
    // A shop-stock entry describes a type, but each purchase makes a new
    // physical instance. Never share the stock id with purchased instances.
    var id='it-bc-'+String(item.id||'stock').replace(/[^a-zA-Z0-9_-]/g,'-')+'-'+(current.length+1);
    var materialized={id:id,name:str(item.name),qty:1,cond:str(item.cond)||'good',
      type:item.type,weight:item.weight,bulk:item.bulk,slot:item.slot,tags:item.tags,
      storage_profile:item.storage_profile,quality:item.quality,durability:item.durability,
      maxDurability:item.maxDurability,material:item.material,
      notes:str(item.notes),provenance:{source:'shop',price:price,location:str(v.current_location)}};
    var received=bcReceive(current,materialized);
    if(!received.ok){setBuyError(received.reason+' No yul spent.');return;}
    var newStock=stock.slice(),newQty=num(item.qty,1)-1;
    if(newQty<=0)newStock.splice(idx,1);
    else newStock[idx]=Object.assign({},item,{qty:newQty});
    var newMoney=num(v.money,0)-price;
    var patch=Object.assign({money:newMoney,shop_stock:newStock,inventory:received.inventory,
      carry_state:bcCarryProfile(received.inventory,obj(v.body_profile),bcWalletProfile(newMoney).weightKg)},bcClockForInventory(v,2));
    setBuyError('');
    try {
      var result;
      if(typeof api.patchVariables==='function')result=api.patchVariables(patch);
      else Object.keys(patch).forEach(function(k){api.setVariable(k,patch[k]);});
      var hid='[UI:BUY] item='+str(item.name)+'; price='+price+' yul; STATE ALREADY APPLIED. Do not add inventory or deduct money again.';
      if(result&&typeof result.then==='function') {
        result.then(function(){tellGM(api,hid,'I buy the '+str(item.name).toLowerCase()+'.');p.toStory();},function(e){setBuyError('Purchase failed to save.');});
      }else{tellGM(api,hid,'I buy the '+str(item.name).toLowerCase()+'.');p.toStory();}
    }catch(e){setBuyError('Purchase failed: '+str(e&&e.message||e));}
  }
  return (
    <div>
      {buyError?<div role="alert" style={{color:"#efb6a5",fontSize:13,marginBottom:10}}>{buyError}</div>:null}
      <Frame className="bc-wallet-summary" pad="12px 14px" style={{ marginBottom: 14, display: "flex", justifyContent: "space-between", alignItems: "center" }}><span style={{ color: C.muted }}>Your purse</span><span style={{ fontFamily: DISPLAY, fontSize: 20, color: C.goldHi }}>{num(v.money).toLocaleString() + " yul"}</span></Frame>
      {stock.length ? (
        <div style={{ marginBottom: 20 }}>
          <H>Currently browsing</H>
          <Frame pad="4px 14px 8px">
            {stock.map(function (item, i) {
              var afford = num(v.money, 0) >= num(item.price, 0);
              return (
                <div key={item.id || i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, padding: "9px 0", borderBottom: "1px solid " + C.lineSoft }}>
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 15.5, color: C.ivory }}>{str(item.name) + (num(item.qty, 1) > 1 ? " \u00d7" + num(item.qty, 1) : "")}</div>
                    {item.notes ? <div style={{ fontSize: 13, color: C.muted }}>{str(item.notes)}</div> : null}
                  </div>
                  <Btn small disabled={busy || !afford} onClick={function () { buyItem(item, i); }} style={{ flexShrink: 0 }}>{"Buy \u2014 " + num(item.price, 0) + " yul"}</Btn>
                </div>
              );
            })}
          </Frame>
        </div>
      ) : null}
      <H>Shops you know</H>
      {shops.length ? <Frame pad="4px 14px 8px">{shops.map(function (l, i) { return <Row key={i} k={str(l.name)} v={str(l.region) || str(l.kingdom)} />; })}</Frame> : <Empty>No shops noted yet. Ask around wherever you are.</Empty>}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", margin: "10px 0 20px" }}>
        <Btn small disabled={busy} onClick={function () { ask("I look for somewhere nearby to buy what I need."); }}>Look for a shop</Btn>
        <Btn small disabled={busy} onClick={function () { ask("I try to sell something I'm carrying."); }}>Sell something</Btn>
      </div>
      <H>The black market</H>
      {shady.length ? <Frame pad="4px 14px 8px">{shady.map(function (x, i) { return <Row key={i} k={str(x.name || x.topic)} v={str(x.notes || x.text).slice(0, 70)} />; })}</Frame> : <Empty>You don't know anyone who deals in that kind of thing. Asking the wrong person can be dangerous.</Empty>}
      <div style={{ marginTop: 10 }}><Btn small disabled={busy} onClick={function () { ask("I quietly ask around about where someone could buy things off the books."); }}>Ask around discreetly</Btn></div>
    </div>
  );
}
function MissionsView(p) {
  var v = p.api.variables || {}; var missions = arr(v.missions);
  var events = arr(v.known_events).filter(function (e) { return e && !/^(done|missed|taken|resolved|expired)$/i.test(str(e.status)); });
  var past = arr(v.known_events).filter(function (e) { return e && /^(done|missed|taken|resolved|expired)$/i.test(str(e.status)); }).slice(-5).reverse();
  return (
